export const VIDEO_TYPE = 'wix-draft-plugin-video';

export const videoButtonsTypes = { video: 'video', youTube: 'youTube' } as const;

export interface VideoPluginEditorConfig {
  type: 'video';
  /**
   * @description Sets default `disableDownload` value for newly uploaded videos.
   */
  disableDownloadDefault?: boolean;

  // @todo: next-major: remove deprecated Promise<string> return value
  /**
   * @description Promise<string> is deprecated, please use string as a return value.
   */
  getVideoUrl?: (src: { pathname: string }) => string | Promise<string>;
  exposeButtons?: (typeof videoButtonsTypes)[keyof typeof videoButtonsTypes][];
}
export interface VideoPluginViewerConfig {
  getVideoUrl?: VideoPluginEditorConfig['getVideoUrl'];
}
