import { Box, Text } from '@wix/design-system';
import classNames from 'classnames';
import React from 'react';

import type { VideoData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { ComponentData, TFunction } from './../../ricos-types/index.js';
import { isCustomUpload } from './../../_shared/is-custom-upload.js';
import type { PmVideoNode } from './../../_shared/pm-node-types.js';
import type { Editor } from './../../tiptap/core/index.js';
import type { ReactPlayer } from './../../wix-react-player/index.js';
import { DoubleLoader, MediaItemErrorMsg } from './../../ui-components/index.js';

import { getContainerClasses } from '../../_shared/figure/get-container-classes.js';
import { VIDEO_ROOT } from '../data-hooks.js';
import styles from '../statics/styles/default-video-styles-scss.js';
import type { VideoPluginEditorConfig } from '../types.js';
import { Video } from '../viewer/video.js';

const isUploading = (videoData: PmVideoNode['attrs']) =>
  videoData?.video?.src?.url?.startsWith?.('blob:') ?? false;

function createFakeProgressStepper(
  onProgress: (percent: number) => void,
  approximateExpectedDuration = 5000
) {
  let lastTimeoutId: NodeJS.Timeout;
  let progress = 0;
  const startDate = Date.now();

  const getTimeoutDelay = () => {
    const linearStep = approximateExpectedDuration / 100;
    if (progress <= 25) {
      return linearStep / 4;
    } else if (progress <= 50) {
      return linearStep / 3;
    } else if (progress <= 90) {
      return linearStep / 1.5;
    } else {
      const timeRemaining = approximateExpectedDuration - (Date.now() - startDate);
      return timeRemaining / (100 - progress);
    }
  };

  const run = () => {
    progress += 1;

    if (progress >= 100) {
      return;
    }

    lastTimeoutId = setTimeout(run, getTimeoutDelay());
    onProgress(progress);
  };

  run();
  return () => {
    clearTimeout(lastTimeoutId);
  };
}

type Props = {
  componentData: PmVideoNode['attrs'];
  isLoading: boolean;
  updateAttributes: (componentData: ComponentData) => void;
  config: VideoPluginEditorConfig;
  nodeId: string;
  t: TFunction;
  editor: Editor;
};

interface State {
  isLoaded: boolean;
  iosFixKey: number;
  shouldRenderDurationFix?: boolean;
  processing: boolean;
  fakeLoadingPercent: number;
}

export class VideoComponent extends React.Component<Props, State> {
  private containerRef: React.RefObject<HTMLDivElement> = React.createRef();

  private durationFixTimeoutId: ReturnType<typeof setTimeout> | undefined;

  private resetFakeLoader?: () => void;

  constructor(props: Props) {
    super(props);
    this.state = {
      isLoaded: false,
      iosFixKey: 1,
      processing: false,
      fakeLoadingPercent: 1,
    };
  }

  componentDidMount() {
    this.handlePlayerFocus();

    if (isUploading(this.props.componentData)) {
      this.startFakeLoader();
    }
  }

  componentDidUpdate(prevProps: Props) {
    this.handlePlayerFocus();

    const wasUploading = isUploading(prevProps.componentData);
    const isNowUploading = isUploading(this.props.componentData);
    const hasTokenChanged =
      prevProps.componentData.uploadToken !== this.props.componentData.uploadToken &&
      this.props.componentData.uploadToken !== null;

    if ((wasUploading && !isNowUploading) || hasTokenChanged) {
      this.resetFakeLoader && this.resetFakeLoader();
    }

    if ((!wasUploading && isNowUploading) || hasTokenChanged) {
      this.startFakeLoader();
    }
  }

  componentWillUnmount(): void {
    clearTimeout(this.durationFixTimeoutId);
    this.resetFakeLoader && this.resetFakeLoader();
  }

  handlePlayerFocus() {
    const element = this.containerRef.current?.querySelector('iframe, video');

    if (element) {
      (element as HTMLElement).tabIndex = -1;
    }
  }

  startFakeLoader = () => {
    if (this.resetFakeLoader) {
      this.resetFakeLoader();
    }

    const isCustomVideo =
      'video' in this.props.componentData &&
      (!!this.props.componentData.video?.src?.id ||
        isCustomUpload(this.props.componentData.video?.src?.url));

    this.resetFakeLoader = createFakeProgressStepper(
      (percent: number) => this.setState({ fakeLoadingPercent: percent }),
      isCustomVideo ? 50000 : 8500
    );
  };

  handleReady = (player: React.MutableRefObject<ReactPlayer | null>) => {
    if (!this.state.isLoaded) {
      this.setState({ isLoaded: true });

      if (!isUploading(this.props.componentData)) {
        this.resetFakeLoader && this.resetFakeLoader();
      }
    }
    this.handleDuration(player);
  };

  handleDuration = (player: React.MutableRefObject<ReactPlayer | null>) => {
    setTimeout(() => {
      const duration = player.current?.getDuration();
      if (duration) {
        this.saveDurationToData(duration);
      } else {
        this.setState({ shouldRenderDurationFix: true });
      }
    }, 3000);
  };

  renderPendingOverlay = ({ title, subtitle }: { title: string; subtitle: string }) => {
    return (
      <div className={styles.video_pending_overlay}>
        <span className={styles.video_pending_overlay_loader}>
          <DoubleLoader />
        </span>
        <Box direction="vertical" gap="0" align="center">
          <Text size="small" weight="bold" light>
            {title}
          </Text>
          <Text size="small" weight="thin" light>
            {subtitle}
          </Text>
        </Box>
      </div>
    );
  };

  saveDurationToData = (duration: number) => {
    const { componentData, updateAttributes } = this.props;
    const video = 'video' in componentData ? componentData.video : {};
    updateAttributes({ ...componentData, video: { ...(video || {}), duration } });
  };

  handleUpdateProcessing = (processing: boolean) => {
    this.setState({ processing });
  };

  renderPlayer = () => {
    const { componentData, config, nodeId } = this.props;

    return (
      <Video
        componentData={componentData as VideoData}
        config={config}
        onReady={this.handleReady}
        isLoaded={this.state.isLoaded}
        key={this.state.iosFixKey}
        nodeId={nodeId}
        isLight={false}
        disabled
        onUpdateProcessing={this.handleUpdateProcessing}
      />
    );
  };

  renderPlayerDurationFix = () => {
    const { componentData, config, nodeId } = this.props;

    const play = (player: React.MutableRefObject<ReactPlayer | null>): boolean => {
      const internalPlayer = player.current?.getInternalPlayer();
      if (internalPlayer && 'play' in internalPlayer && typeof internalPlayer.play === 'function') {
        internalPlayer.play();
        return true;
      }

      return false;
    };

    // In some instances the video doesn't completely load, and we don't get its duration. This is a fix for that. (happens in facebook)
    const onReady = (player: React.MutableRefObject<ReactPlayer | null>) => {
      const hasPlayed = play(player);
      if (hasPlayed) {
        return;
      }
      // try again, sometimes it takes a while
      this.durationFixTimeoutId = setTimeout(() => {
        play(player);
      }, 10000);
    };

    return (
      <div className={styles.hide_duration}>
        <Video
          componentData={componentData as VideoData}
          config={config}
          onReady={onReady}
          isLight={false}
          onDuration={duration => {
            this.setState({ shouldRenderDurationFix: false });
            this.saveDurationToData(duration);
            clearTimeout(this.durationFixTimeoutId);
          }}
          nodeId={nodeId}
          muted
          onUpdateProcessing={this.handleUpdateProcessing}
        />
      </div>
    );
  };

  getOverlayProps = () => {
    const { t } = this.props;
    const { isLoaded, processing } = this.state;
    const loading = this.props.isLoading || !isLoaded;
    const uploading = isUploading(this.props.componentData);

    if (processing) {
      return {
        title: t('VideoComponent_Processing_Title'),
        subtitle: t('VideoComponent_Processing_Subtitle'),
      };
    }

    if (loading && !this.props.componentData.error) {
      return {
        title: uploading ? t('VideoComponent_Uploading_Title') : t('VideoComponent_Loading_Title'),
        subtitle: uploading
          ? t('VideoComponent_Uploading_Subtitle', {
              percent: Math.round(this.state.fakeLoadingPercent),
            })
          : t('VideoComponent_Loading_Subtitle'),
      };
    }

    return null;
  };

  render() {
    const {
      t,
      componentData: { error },
    } = this.props;

    const { shouldRenderDurationFix } = this.state;
    const overlayProps = this.getOverlayProps();

    return (
      <div
        ref={this.containerRef}
        data-hook={VIDEO_ROOT}
        className={classNames(
          styles.video_container,
          getContainerClasses(this.props.editor, this.props.nodeId, false)
        )}
      >
        <div className={styles.video_overlay} />
        {this.renderPlayer()}
        {shouldRenderDurationFix ? this.renderPlayerDurationFix() : null}
        {overlayProps && this.renderPendingOverlay(overlayProps)}
        {error && <MediaItemErrorMsg error={error} t={t} />}
      </div>
    );
  }
}
