import type {
  UpdateEntityFileSelectFunc,
  UpdateEntityFileUploadFunc,
  VideoComponentData,
} from './../ricos-content/index.js';
import { VIDEO_TYPE } from './../ricos-content/index.js';
import type { PluginServices } from './../ricos-plugins/editor-plugins.js';
import type { PublicCommands } from './../ricos-types/index.js';
import { getHighestQualityVideo } from './../_shared/get-highest-quality-video.js';
import { getUploadError } from './../_shared/get-upload-error.js';
import { logInvariant } from './../_shared/log-invariant.js';
import { createOpenMediaManagerFn } from './../_shared/media-manager/create-open-media-manager-fn.js';
import { MediaManagerMediaType } from './../_shared/media-manager/types.js';
import type { PickMediaFn } from './../_shared/media/pick-media.js';
import type { PickMediaVideoData, PublicPickMedia } from './../_shared/media/public-pick-media.js';
import type { PmVideoNode } from './../_shared/pm-node-types.js';
import { MediaType } from './../_shared/request-service-provider/consts.js';
import { createUploadFn } from './../_shared/request-service-provider/media-manager-uploader.js';
import type {
  MediaManagerSDKError,
  RawVideoData,
} from './../_shared/request-service-provider/upload-types.js';
import { unreachable } from './../_shared/uncreachable.js';
import { upload } from './../_shared/upload/upload.js';
import { withFileSizeLimitation } from './../_shared/with-file-size-limitation.js';

import { RICOS_DEFAULTS } from './constants.js';
import type { VideoPluginEditorConfig } from './types.js';

const isPickMediaType = (
  data: (VideoComponentData & { url?: string }) | PickMediaVideoData
): data is PickMediaVideoData => 'type' in data && data.type === 'video';

const getVideoAttributes = ({
  uploadData,
  componentData,
  config,
}: {
  uploadData: (VideoComponentData & { url?: string }) | PickMediaVideoData;
  componentData: PmVideoNode['attrs'] | null;
  config: Pick<VideoPluginEditorConfig, 'disableDownloadDefault'>;
}) => {
  const disableDownload = componentData?.video?.src
    ? componentData.disableDownload
    : config.disableDownloadDefault || null;

  if (isPickMediaType(uploadData)) {
    return {
      video: { src: uploadData.src },
      ...(uploadData.thumbnail
        ? {
            thumbnail: uploadData.thumbnail,
          }
        : {}),
      ...(uploadData.title ? { title: uploadData.title } : {}),
      disableDownload,
    };
  }
  const { pathname, thumbnail: uploadedThumbnail, url: uploadedUrl, title } = uploadData;

  const src = pathname ? { id: pathname } : { url: uploadedUrl };
  const thumbnailObject = uploadedThumbnail
    ? {
        thumbnail: {
          src: { id: uploadedThumbnail.pathname },
          width: uploadedThumbnail.width,
          height: uploadedThumbnail.height,
        },
      }
    : {};

  const titleObject = title ? { title } : {};

  return {
    video: { src },
    ...thumbnailObject,
    ...titleObject,
    disableDownload,
  };
};

const getVideoPickMedia = ({
  services,
  handleFileUpload,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  handleFileUpload: ReturnType<typeof createHandleFileUploadFn>;
}): PickMediaFn | PublicPickMedia['pickVideo'] => {
  const editorPickMedia = services.editorProps.pickMedia?.pickVideo;
  const devPickMedia = services.devService().pickMedia;
  const handleFileSelection =
    services.devService().handleFileSelection ?? createHandleFileSelectionFn(services);

  return devPickMedia
    ? devPickMedia
    : editorPickMedia
      ? editorPickMedia
      : handleFileSelection
        ? async () => {
            try {
              const data = await new Promise<VideoComponentData>((resolve, reject) =>
                handleFileSelection(({ data }) => resolve(data), reject)
              );
              return { type: 'ready-media' as const, media: [data] };
            } catch {
              return { type: 'cancel' as const };
            }
          }
        : async ({ mimeType, multiple }: Parameters<PickMediaFn>[0]) => {
            const files =
              (await services.uploadService?.selectFiles({ accept: mimeType, multiple })) ?? [];
            return { type: 'file' as const, file: files, customUploadFn: handleFileUpload };
          };
};

export const handleVideoUpload = async ({
  services,
  config,
  publicCommands,
  nodeId,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'wixInstance' | 'editorProps' | 'modals'
  >;
  config: Pick<VideoPluginEditorConfig, 'disableDownloadDefault'>;
  publicCommands: PublicCommands;
  nodeId?: string;
}) => {
  const handleFileUpload = createHandleFileUploadFn(services);

  const pickMedia = getVideoPickMedia({ services, handleFileUpload });

  const result = await pickMedia({ mimeType: 'video/*', multiple: false }).catch(() => ({
    type: 'cancel' as const,
  }));

  const clearUploadToken = (targetNodeId: string) => {
    publicCommands?.setBlock(targetNodeId, VIDEO_TYPE, {
      ...publicCommands?.getBlockComponentData(targetNodeId),
      uploadToken: null,
    });
  };

  const getUploadToken = (targetNodeId: string) => {
    return publicCommands?.getBlockComponentData(targetNodeId)?.uploadToken;
  };

  switch (result.type) {
    case 'ready-media': {
      const data = (result.media[0] as VideoComponentData | PickMediaVideoData) || {};
      if (nodeId) {
        const componentData: PmVideoNode['attrs'] = publicCommands?.getBlockComponentData(nodeId);

        publicCommands?.setBlock(nodeId, VIDEO_TYPE, {
          ...componentData,
          ...getVideoAttributes({ uploadData: data, componentData, config }),
        } satisfies PmVideoNode['attrs']);
        return;
      }

      queueMicrotask(() => {
        publicCommands.insertBlockWithBlankLines(
          VIDEO_TYPE,
          {
            ...getVideoAttributes({
              uploadData: data,
              componentData: null,
              config,
            }),
            ...RICOS_DEFAULTS,
          },
          {
            updateSelection: true,
          }
        );
      });
      return;
    }
    case 'file': {
      const files = result.file;

      const targetNodeId =
        nodeId ||
        publicCommands.insertBlockWithBlankLines(
          VIDEO_TYPE,
          {
            ...RICOS_DEFAULTS,
            loading: true,
          },
          {
            updateSelection: true,
          }
        );

      const uploadToken = Symbol('upload-token');

      const file = Array.isArray(files) ? files[0] : files;
      const trackBi = services.uploadService.trackUploadBi(VIDEO_TYPE, file.size, file.name);

      try {
        const url = URL.createObjectURL(file);
        await Promise.resolve();

        publicCommands?.setBlock(targetNodeId, VIDEO_TYPE, {
          ...publicCommands?.getBlockComponentData(targetNodeId),
          video: {
            src: { url },
          },
          disableDownload: config.disableDownloadDefault,
          loading: true,
          error: null,
          uploadToken,
        });

        trackBi?.start();
        const uploadFn = result.customUploadFn || handleFileUpload;

        if (!uploadFn) {
          logInvariant(Error('No upload function provided'));
          throw new Error('No upload function provided');
        }

        const uploadedFile = await upload(uploadFn, file);
        if (getUploadToken(targetNodeId) !== uploadToken) {
          URL.revokeObjectURL(url as string);
          return;
        }

        const uploadData =
          (uploadedFile.data as VideoComponentData & { url: string | undefined }) || {};

        const componentData = publicCommands?.getBlockComponentData(targetNodeId);

        publicCommands?.setBlock(targetNodeId, VIDEO_TYPE, {
          ...componentData,
          ...getVideoAttributes({ uploadData, componentData, config }),
          tempData: null,
          loading: null,
          error: null,
        } satisfies PmVideoNode['attrs']);

        URL.revokeObjectURL(url as string);
        trackBi?.success();
      } catch (error: any) {
        if (getUploadToken(targetNodeId) === uploadToken) {
          const componentData = publicCommands?.getBlockComponentData(targetNodeId);
          publicCommands?.setBlock(targetNodeId, VIDEO_TYPE, {
            ...componentData,
            error,
            loading: null,
          });

          trackBi?.error(error);
          services.uploadService.notifyError(error);
        }
      } finally {
        if (getUploadToken(targetNodeId) === uploadToken) {
          clearUploadToken(targetNodeId);
        }
      }
      return;
    }
    case 'cancel': {
      services.modals.notifyExternalModalClosed();
      return;
    }
    default: {
      console.error(unreachable(result));
      return;
    }
  }
};

const createHandleFileUploadFn = (
  services: Pick<PluginServices, 'wixInstance' | 'editorProps'>
) => {
  const { metaSiteId, uid, siteOwnerId } = services.wixInstance();

  if (!metaSiteId) {
    return undefined;
  }

  const videoUpload = (
    file: File,
    updateEntity: UpdateEntityFileUploadFunc<VideoComponentData>
  ) => {
    const upload = createUploadFn(services);

    return upload(file, MediaType.VIDEO)
      .then(({ file_output: { video, image } }: RawVideoData) => {
        updateEntity({
          data: {
            pathname: getHighestQualityVideo(video).url,
            thumbnail: {
              pathname: image[0].url,
              width: image[0].width,
              height: image[0].height,
            },
            title: file.name,
          },
        });
      })
      .catch((error: MediaManagerSDKError) => {
        const isOwner = siteOwnerId === uid;
        const mediaUploadError = getUploadError(error, metaSiteId, isOwner);
        updateEntity({ error: mediaUploadError });
      });
  };

  return withFileSizeLimitation(videoUpload, services.editorProps.fileUploadSizeLimit);
};

const createHandleFileSelectionFn = (services: Pick<PluginServices, 'wixInstance' | 'modals'>) => {
  const openMediaManager = createOpenMediaManagerFn(services.modals);
  if (!openMediaManager) {
    return undefined;
  }
  return (updateEntity: UpdateEntityFileSelectFunc<VideoComponentData>, onCancel: () => void) =>
    openMediaManager({
      mediaType: MediaManagerMediaType.VIDEO,
      appDefId: services.wixInstance().appDefId,
    })
      .then(items => {
        const { fullTitle, title, fileOutput } = items[0];
        const { video, image } = fileOutput;
        const { url: pathname } = getHighestQualityVideo(video);
        const { url, width, height } = image[0];
        const thumbnail = { pathname: url, width, height };
        const videoTitle = (fullTitle ?? title) as string | undefined;
        const titleObject = videoTitle ? { title: videoTitle } : {};
        updateEntity({ data: { pathname, thumbnail, ...titleObject } });
      })
      .catch(onCancel);
};
