import React, { useContext } from 'react';

import { RicosContext } from './../../ricos-context/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import type { PmVideoNode } from './../../_shared/pm-node-types.js';

import type { VideoPluginEditorConfig } from '../types.js';
import { VideoComponent } from './video-component.js';

export const Video: React.FC<PluginProps> = ({
  settings,
  componentData,
  updateAttributes,
  node,
  editor,
}) => {
  const { t } = useContext(RicosContext);
  const { loading, id } = node.attrs;

  return (
    <VideoComponent
      key={componentData.video?.src?.url || componentData.video?.src?.id}
      componentData={componentData as PmVideoNode['attrs']}
      t={t}
      config={settings as VideoPluginEditorConfig}
      updateAttributes={updateAttributes}
      isLoading={loading}
      nodeId={id}
      editor={editor}
    />
  );
};
