import { definePmNodeConverter } from './../../pm-converters/types.js';
import { TIPTAP_FIGURE_TYPE, TIPTAP_VIDEO_TYPE } from './../../ricos-content/consts.js';
import { generateId } from './../../ricos-content/index.js';
import type { CaptionNode, Node, TextNode, VideoNode } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';

export const videoConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.VIDEO],
    convert: (node, visit) => {
      const fallbackCaption = {
        id: generateId(),
        type: Node_Type.CAPTION,
        nodes: [],
      } as unknown as Node;

      return {
        type: TIPTAP_FIGURE_TYPE,
        attrs: {
          id: generateId(),
        },
        content: [
          {
            type: TIPTAP_VIDEO_TYPE,
            attrs: {
              ...node.videoData,
              id: node.id,
            },
          },
          ...(visit?.(
            (node.nodes?.length ?? 0) > 0
              ? node
              : ({ ...node, nodes: [fallbackCaption] } as VideoNode)
          ) ?? []),
        ],
      };
    },
  },
  fromPm: {
    types: [TIPTAP_FIGURE_TYPE, TIPTAP_VIDEO_TYPE],
    convert: (node, visit) => {
      if (node.type === TIPTAP_VIDEO_TYPE) {
        return undefined;
      }
      const videoNode = node.content?.find(({ type }) => type === TIPTAP_VIDEO_TYPE);

      if (!videoNode) {
        return undefined;
      }

      const { id, loading, error, animation, ...data } = videoNode?.attrs || {};

      if (loading || error) {
        return undefined;
      }

      const [captionNode] = visit?.(node) ?? [];

      const { spoiler, ...rest } = data.containerData || {};
      const containerData = {
        ...rest,
        ...(spoiler?.enabled ? { spoiler: { ...spoiler } } : {}),
      };

      return {
        type: Node_Type.VIDEO,
        id: id ?? generateId(),
        nodes: (captionNode?.nodes?.[0] as TextNode | undefined)?.textData?.text
          ? [captionNode as CaptionNode]
          : [],
        videoData: {
          ...data,
          disableDownload: data.disableDownload || undefined,
          containerData: Object.keys(containerData).length ? containerData : undefined,
          ...(animation ? { animation } : {}),
        },
      } as unknown as VideoNode;
    },
  },
});
