import { Box, FormField, SegmentedToggle } from '@wix/design-system';
import { LinkSmall, UploadExportSmall } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import {
  ModalServiceContext,
  PluginsEventsContext,
  RicosContext,
  UploadContext,
} from './../../ricos-context/index.js';
import type { VideoData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { MEDIA_POPOVERS_TABS_NAMES_BI } from './../../wix-rich-content-common/index.js';
import { Panel, PanelHeader } from './../../ui-components/index.js';

import { INSERT_VIDEO_MODAL, INSERT_VIDEO_MODAL_SOURCE_TOGGLE } from '../data-hooks.js';
import { EmbedVideo } from '../toolbar/embed-video.js';
import { UploadVideo } from '../toolbar/upload-video.js';
import type { VideoPluginEditorConfig } from '../types.js';
import { VIDEO_TYPE } from '../types.js';

type InsertModalProps = Pick<VideoPluginEditorConfig, 'disableDownloadDefault'> & {
  componentData: VideoData;
  modalId: string;
  nodeId?: string;
};

const SourceOptionValue = {
  EMBED: 'embed',
  UPLOAD: 'upload',
} as const;

type SourceOption = (typeof SourceOptionValue)[keyof typeof SourceOptionValue];

export const InsertModal: FC<InsertModalProps> = ({
  nodeId,
  modalId,
  componentData,
  disableDownloadDefault,
}) => {
  const { t } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext) || {};
  const pluginsEvents = useContext(PluginsEventsContext);
  const { uploadService, updateService } = useContext(UploadContext);
  const logBi = useBiNext({ modalId, pluginId: 'video', nodeId });

  const [selectedSource, setSelectedSource] = useState<SourceOption>(
    componentData?.video?.src?.id ? 'upload' : 'embed'
  );

  const pluginEvents = {
    onPluginsPopOverTabSwitch: (data: $TSFixMe) =>
      pluginsEvents.publishPluginPopoverTabSwitch(data),
    onPluginsPopOverClick: (data: $TSFixMe) => pluginsEvents.publishPluginPopoverClick(data),
  };

  const closeModal = () => {
    modalService.closeModal(modalId);
  };

  const onSourceToggleClick = (_: React.SyntheticEvent, value: string) => {
    selectedSource !== value &&
      pluginEvents.onPluginsPopOverTabSwitch?.({
        pluginId: VIDEO_TYPE,
        buttonName: getTabsBiButtonName(value as SourceOption),
      });
    setSelectedSource(value as SourceOption);
    logBi({ dataHook: INSERT_VIDEO_MODAL_SOURCE_TOGGLE, value });
  };

  return (
    <Panel
      closeButtonProps={{ onClick: closeModal }}
      dataHook={INSERT_VIDEO_MODAL}
      height="fit-content"
    >
      <PanelHeader title={t('Video_Modal_Header_Title')} />

      <Box direction="vertical" padding="SP3" gap="SP3">
        <FormField label={t('Audio_Modal_Toggle_Source_Label')}>
          <SegmentedToggle
            defaultSelected={selectedSource}
            size="small"
            onClick={onSourceToggleClick}
            dataHook={INSERT_VIDEO_MODAL_SOURCE_TOGGLE}
          >
            <SegmentedToggle.Button value={SourceOptionValue.EMBED} prefixIcon={<LinkSmall />}>
              {t('VideoModal_Tabs_Embed')}
            </SegmentedToggle.Button>
            <SegmentedToggle.Button
              value={SourceOptionValue.UPLOAD}
              prefixIcon={<UploadExportSmall />}
            >
              {t('VideoModal_Tabs_Upload')}
            </SegmentedToggle.Button>
          </SegmentedToggle>
        </FormField>
        {selectedSource === 'embed' && (
          <EmbedVideo
            nodeId={nodeId}
            componentData={componentData}
            helpers={pluginEvents}
            closeModal={closeModal}
            logBi={logBi}
          />
        )}
        {selectedSource === 'upload' && (
          <UploadVideo
            nodeId={nodeId}
            helpers={pluginEvents}
            uploadService={uploadService}
            updateService={updateService}
            closeModal={closeModal}
            disableDownloadDefault={disableDownloadDefault}
            logBi={logBi}
          />
        )}
      </Box>
    </Panel>
  );
};

const getTabsBiButtonName = (source: SourceOption) =>
  source === 'embed' ? MEDIA_POPOVERS_TABS_NAMES_BI.embed : MEDIA_POPOVERS_TABS_NAMES_BI.upload;
